mapper.select:

WHERE summary_id = #{summaryId}
  AND task_id = #{taskId}
  AND qr_code = #{qrCode}
LIMIT 1




        AND qr_code LIKE CONCAT('%', #{qrCode}, '%')


        AND work_order_code LIKE CONCAT('%', #{workOrderCode}, '%')


        AND task_id = #{taskId}


        AND upload_status = #{uploadStatus}


        AND date_format(create_time,'%Y-%m-%d') >= #{params.beginTime}


        AND date_format(create_time,'%Y-%m-%d') <= #{params.endTime}


ORDER BY create_time DESC
